#' Cross Tables (Python Core)
#'
#' 
#' @param data .
#' @param vars .
#' @param group .
#' @param excl .
#' @param cont .
#' @param pcat .
#' @param p_adjust .
#' @param numericMode .
#' @param showTyping .
#' @param showTestDetails .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$continuous} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$categories} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$tests} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$typing} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pycrosstable <- function(
    data,
    vars = NULL,
    group = NULL,
    excl = FALSE,
    cont = "mean",
    pcat = "chisq",
    p_adjust = "none",
    numericMode = "auto",
    showTyping = FALSE,
    showTestDetails = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pycrosstable requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(group), group, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pycrosstableOptions$new(
        vars = vars,
        group = group,
        excl = excl,
        cont = cont,
        pcat = pcat,
        p_adjust = p_adjust,
        numericMode = numericMode,
        showTyping = showTyping,
        showTestDetails = showTestDetails,
        showConsole = showConsole)

    analysis <- pycrosstableClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

